import{H as e,V as t,et as n,j as r}from"./chunks/framework.ChZHrXbO.js";import{Wo as i}from"./chunks/assets.BxHYjuf8.js";var a=JSON.parse(`{"title":"日志","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/logs.md","filePath":"mysql/logs.md"}`),o={name:`mysql/logs.md`};function s(r,a,o,s,c,l){return n(),t(`div`,null,[...a[0]||=[e(`<h1 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to “日志”">​</a></h1><h2 id="_1-错误日志" tabindex="-1">1.错误日志 <a class="header-anchor" href="#_1-错误日志" aria-label="Permalink to “1.错误日志”">​</a></h2><p>错误日志是 MySQL 中最重要的日志之一，它记录了当 mysqld 启动和停止时，以及服务器在运行过程中发生任何严重错误时的相关信息，当数据库出现任何故障导致无法正常使用时，建议首先查看此日志。</p><p>该日志是默认开启的，默认存放目录 /var/log/，默认的日志文件名为 mysqld.log 。</p><p>查看日志位置：</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show variables </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">like</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%log_error%&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">-- log_error</span></span></code></pre></div><h2 id="_2-二进制日志" tabindex="-1">2.二进制日志 <a class="header-anchor" href="#_2-二进制日志" aria-label="Permalink to “2.二进制日志”">​</a></h2><h3 id="_2-1-介绍" tabindex="-1">2.1 介绍 <a class="header-anchor" href="#_2-1-介绍" aria-label="Permalink to “2.1 介绍”">​</a></h3><p>二进制日志(BINLOG)记录了所有的 DDL(数据定义语言)语句和 DML(数据操纵语言)语句，但不包括数据查询(SELECT、SHOW)语句。</p><p>作用：</p><ol><li><p>灾难时的数据恢复</p></li><li><p>MySQL的主从复制</p></li></ol><p>在MVSOL8版本中，默认二进制日志是开启着的，涉及到的参数如下：</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show variables </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">like</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%log_bin%&#39;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"> -- log_bin</span></span></code></pre></div><p><img src="`+i+'" alt="e66e4a093c394734adccea64f8fe241cpng" width="1110" height="223"></p><h3 id="_2-2-日志格式" tabindex="-1">2.2 日志格式 <a class="header-anchor" href="#_2-2-日志格式" aria-label="Permalink to “2.2 日志格式”">​</a></h3><p>MySQL服务器中提供了多种格式来记录二进制记录，具体格式及特点如下：</p><table tabindex="0"><thead><tr><th>日志格式</th><th>含义</th></tr></thead><tbody><tr><td>statement</td><td>基于SQL语句的日志记录，记录的是SQL语句，对数据进行修改的SQL都会记录在日志文件中。</td></tr><tr><td>row</td><td>基于行的日志记录，记录的是每一行的数据变更。(默认)</td></tr><tr><td>mined</td><td>混合了STATEMENT和ROW两种格式，默认采用STATEMENT，在某些特殊情况下会自动切换为ROW进行记录。</td></tr></tbody></table><p>查看参数方式</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show variables </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">like</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%binlog_format%&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">-- binlog_format</span></span></code></pre></div><p>修改参数</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> binlog_format </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> statement</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">row</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|mined;</span></span></code></pre></div><h3 id="_2-3-日志查看" tabindex="-1">2.3 日志查看 <a class="header-anchor" href="#_2-3-日志查看" aria-label="Permalink to “2.3 日志查看”">​</a></h3><p>由于日志是以二进制方式存储的，不能直接读取，需要通过二进制日志查询工具 mysqlbinlog 来查看。</p><div class="language-Properties"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Properties</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqlbinlog [参数选项] logfilename</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">参数选项：</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    -d    指定数据库名称，只列出指定的数据库相关的操作。</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    -o    忽略掉日志中的前n行命令。</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    -v    将行事件(数据变更)重构为SOL语句。</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    -w    将行事件(数据变更)重构为SQL语句，并输出注释信息</span></span></code></pre></div><h3 id="_2-4-日志删除" tabindex="-1">2.4 日志删除 <a class="header-anchor" href="#_2-4-日志删除" aria-label="Permalink to “2.4 日志删除”">​</a></h3><p>对于比较繁忙的业务系统，每天生成的binlog数据巨大，如果长时间不清除，将会占用大量磁盘空间。可以通过以下几种方式清理日志：</p><table tabindex="0"><thead><tr><th>指令</th><th>含义</th></tr></thead><tbody><tr><td><code>reset master;</code></td><td>删除全部 binlog 日志，删除之后，日志编号将从 binlog.000001重新开始</td></tr><tr><td><code>purge master logs to ``&#39;``binlog.***``&#39;``;</code></td><td>删除 *** 编号之前的所有日志</td></tr><tr><td><code>purge master logs before ``&#39;``yyyy-mm-dd hh24:mi:ss``&#39;``;</code></td><td>删除日志为”yyyy-mm-dd hh24:mi:ss”之前产生的所有日志</td></tr></tbody></table><p>也可以在mysql的配置文件中配置二进制日志的过期时间，设置了之后，二进制日志过期会自动删除.</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show variables </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">like</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%binlog_expire_logs_seconds%&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">-- binlog_expire_logs_seconds</span></span></code></pre></div><p>设置过期时间</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> global</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> binlog_expire_logs_seconds </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> seconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="_3-查询日志" tabindex="-1">3.查询日志 <a class="header-anchor" href="#_3-查询日志" aria-label="Permalink to “3.查询日志”">​</a></h2><p>查询日志中记录了客户端的所有操作语句，而二进制日志不包含查询数据的SQL语句。默认情况下，查询日志是未开启的。如果需要开启查询日志，可以设置一下配置：</p><p>修改MySQL的配置文件my.cnf或my.ini 文件，添加如下内容：</p><div class="language-Properties"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Properties</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">#该选项用来开启查询日志，可选值：0或者1；0代表关闭，1代表开启</span></span>\n<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">general_log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1</span></span>\n<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">#设置日志的文件名，如果没有指定，默认的文件名为 host_name.log</span></span>\n<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">general_log_file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=mysql_query.log</span></span></code></pre></div><h2 id="_4-慢查询日志" tabindex="-1">4.慢查询日志 <a class="header-anchor" href="#_4-慢查询日志" aria-label="Permalink to “4.慢查询日志”">​</a></h2><p>慢查询日志记录了所有执行时间超过参数 long_query_time 设置值并且扫描记录数不小于 min_examined_row_limit 的所有的SQL语句的日志，默认未开启。long_query_time 默认为 10 秒，最小为0，精度可以到微秒。</p><div class="language-Properties"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Properties</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">#慢查询日志</span></span>\n<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">slow_query_log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1</span></span>\n<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">#执行时间参数</span></span>\n<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">long_query_time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=2</span></span></code></pre></div><p>默认情况下，不会记录管理语句，也不会记录不使用索引进行查找的查询。可以使用log_slow_admin_statements和更改此行为log_queries_not_using_indexes</p><div class="language-Properties"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">Properties</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">#记录执行较慢的管理语句</span></span>\n<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">log_slow_admin_statements</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 1</span></span>\n<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">#记录执行较慢的未使用索引的语句</span></span>\n<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">log_queries_not_using_indexes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 1</span></span></code></pre></div>',40)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};